import { Match as M, Option, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Toast from "../../ui/shadcn-toast";
const primitiveEntryClassesKey = `${"entry"}${"Class"}${"Name"}` as const;
const primitiveContainerClassesKey = `${"container"}${"Class"}${"Name"}` as const;


// MODEL

export const Model = S.Struct({
  toast: Toast.Model,
});
export type Model = typeof Model.Type;

// MESSAGE

export const ClickedShowToast = m("ClickedShowToast");
export const GotToastMessage = m("GotToastMessage", {
  message: Toast.Message,
});

export const Message = S.Union([ClickedShowToast, GotToastMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [
  {
    toast: Toast.init({ id: "toast-basic" }),
  },
  [],
];

// UPDATE

const updateToast = (
  model: Model,
  toast: Toast.Model,
  commands: readonly Command.Command<Toast.Message>[],
  maybeOutMessage: Option.Option<Toast.OutMessage>
): readonly [Model, readonly Command.Command<Message>[]] => {
  Option.match(maybeOutMessage, {
    onNone: () => undefined,
    onSome: M.type<Toast.OutMessage>().pipe(
      M.tagsExhaustive({
        DismissedToast: () => undefined,
      })
    ),
  });

  return [
    evo(model, {
      toast: () => toast,
    }),
    Command.mapMessages(commands, (message) => GotToastMessage({ message })),
  ];
};

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedShowToast: () => {
        const [toast, commands, maybeOutMessage] = Toast.show(model.toast, {
          variant: "Info",
          sticky: true,
          payload: {
            title: "Scheduled: Catch up",
            maybeDescription: Option.some("Friday, February 10, 2023 at 5:57 PM"),
          },
        });

        return updateToast(model, toast, commands, maybeOutMessage);
      },
      GotToastMessage: ({ message }) => {
        const [toast, commands, maybeOutMessage] = Toast.update(
          model.toast,
          message
        );

        return updateToast(model, toast, commands, maybeOutMessage);
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.button(
        [
          h.Type("button"),
          h.Class(
            "inline-flex cursor-pointer items-center rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-900 transition hover:bg-gray-100"
          ),
          h.OnClick(ClickedShowToast()),
        ],
        ["Show toast"]
      ),
      h.submodel({
        slotId: model.toast.id,
        model: model.toast,
        view: Toast.view,
        viewInputs: {
          position: "BottomRight",
          entryToView: Toast.shadcnToastEntryView,
          [primitiveEntryClassesKey]: Toast.shadcnToastEntryClasses,
          [primitiveContainerClassesKey]: Toast.shadcnToastContainerClasses,
        },
        toParentMessage: (message) => GotToastMessage({ message }),
      }),
    ]
  );
});

import { Scene, Ui } from "foldkit";
import { describe, test } from "vitest";

import * as Toast from "../../../foldkit/ui/toast";
import * as ShadcnToastBasicExample from "./main";

const toAnimationMessage = (message: Ui.Animation.Message) =>
  ShadcnToastBasicExample.GotToastMessage({
    message: Toast.GotAnimationMessage({
      entryId: "toast-basic-entry-0",
      message,
    }),
  });

const resolveEntryAnimation = () =>
  Scene.Command.resolveAll(
    [
      Ui.Animation.RequestFrame,
      Ui.Animation.AdvancedAnimationFrame(),
      toAnimationMessage,
    ],
    [
      Ui.Animation.WaitForAnimationSettled({
        id: "toast-basic-entry-0",
      }),
      Ui.Animation.EndedAnimation(),
      toAnimationMessage,
    ]
  );

describe("Shadcn Toast Basic example", () => {
  test("shows the upstream scheduled toast copy", () => {
    Scene.scene(
      {
        update: ShadcnToastBasicExample.update,
        view: ShadcnToastBasicExample.view,
      },
      Scene.with(ShadcnToastBasicExample.init()[0]),
      Scene.click(Scene.role("button", { name: "Show toast" })),
      resolveEntryAnimation(),
      Scene.expect(Scene.role("status")).toExist(),
      Scene.expect(Scene.text("Scheduled: Catch up")).toExist(),
      Scene.expect(Scene.text("Friday, February 10, 2023 at 5:57 PM")).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss Scheduled: Catch up" })),
      Scene.expect(Scene.role("status")).toHaveAttr("data-leave", ""),
      resolveEntryAnimation()
    );
  });
});
